static int MyAcos(int c)
{
    {
        int a;

        a = -c + 0x1000;
        a >>= 1;
        if (a == 0x800)
            a = 0x7ff;
        a += 0x800;
        a &= 0xfff;
        return ArcCos[a];
    }
}

